WITH base AS (SELECT *, GREATEST(units, revenue) AS greatest_units_revenue, revenue - units AS revenue_per_unit FROM store_sales WHERE sale_date > DATE '2023-07-19'), metrics AS (SELECT *, SUM(revenue) OVER w_grp AS running_sum_revenue, MAX(revenue) OVER w_grp AS running_max_revenue, AVG(revenue) OVER w_grp AS running_avg_revenue, MIN(revenue) OVER w_grp AS running_min_revenue, NTILE(4) OVER (PARTITION BY store_id ORDER BY greatest_units_revenue DESC, id) AS greatest_units_revenue_bucket FROM base WINDOW w_grp AS (PARTITION BY product_id ORDER BY revenue, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), latest AS (SELECT *, RANK() OVER (PARTITION BY store_id ORDER BY units) AS rn FROM metrics QUALIFY rn = 1), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY running_avg_revenue DESC NULLS FIRST, id) AS dedup_rank FROM latest QUALIFY dedup_rank = 1), with_dims AS (SELECT src.id, src.store_id, src.product_id, src.units, src.revenue, src.running_sum_revenue, src.running_avg_revenue, src.running_min_revenue, src.greatest_units_revenue_bucket, src.rn, src.dedup_rank, d.category, d.product_name FROM deduped src LEFT JOIN products d ON src.product_id = d.id WHERE d.stock_qty >= 298), joined AS (SELECT e.id, e.store_id, e.revenue, e.running_sum_revenue, e.greatest_units_revenue_bucket, e.rn, e.product_name, s.opened_date FROM with_dims e LEFT JOIN stores s ON e.store_id = s.id) SELECT CASE WHEN revenue >= 4400 THEN 'HIGH' ELSE 'LOW' END AS revenue_tier, DATE_TRUNC('WEEK', opened_date) AS week_start, CASE WHEN running_sum_revenue >= 15900 THEN 'HIGH' ELSE 'LOW' END AS running_sum_revenue_tier, SUM(revenue) AS total_revenue, APPROX_PERCENTILE(greatest_units_revenue_bucket, 0.5) AS greatest_units_revenue_bucket_p50 FROM joined GROUP BY CASE WHEN revenue >= 4400 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('WEEK', opened_date), CASE WHEN running_sum_revenue >= 15900 THEN 'HIGH' ELSE 'LOW' END HAVING total_revenue < 1000000 ORDER BY revenue_tier DESC
